## 4. Persistência Unificada (substitui `CursoFile`/`QuestionarioFile`)

```java
// infra/ClassFileLoader.java
package infra;

import business.model.Curso;
import business.model.Questionario;
import java.io.*;
import java.util.HashMap;
import java.util.Map;
import java.util.logging.Logger;

public class ClassFileLoader {

    private static final Logger log = Logger.getLogger(ClassFileLoader.class.getName());

    public Map<String, Curso> loadCursos() throws InfraException {
        Map<String, Curso> cursos = new HashMap<>();
        try {
            File f = new File("curso.bin");
            if (f.exists()) {
                InputStream in = new FileInputStream(f);
                ObjectInputStream oi = new ObjectInputStream(in);
                cursos = (Map<String, Curso>) oi.readObject();
                oi.close(); in.close();
            }
        } catch (Exception e) {
            throw new InfraException("Erro ao carregar cursos: " + e.getMessage(), e);
        }
        if (cursos.isEmpty()) salvarCursos(cursos); // cria arquivo vazio se necessário
        return cursos;
    }

    public Map<String, Questionario> loadQuestionarios() throws InfraException {
        Map<String, Questionario> qs = new HashMap<>();
        try {
            File f = new File("questionarios.bin");
            if (f.exists()) {
                InputStream in = new FileInputStream(f);
                ObjectInputStream oi = new ObjectInputStream(in);
                qs = (Map<String, Questionario>) oi.readObject();
                oi.close(); in.close();
            }
        } catch (Exception e) {
            throw new InfraException("Erro ao carregar questionários: " + e.getMessage(), e);
        }
        if (qs.isEmpty()) salvarQuestionarios(qs);
        return qs;
    }

    private void salvarCursos(Map<String, Curso> cursos) {
        try {
            FileOutputStream out = new FileOutputStream("curso.bin");
            ObjectOutputStream oo = new ObjectOutputStream(out);
            oo.writeObject(cursos);
            oo.close(); out.close();
        } catch (IOException e) {
            throw new InfraException("Falha ao persistir cursos: " + e.getMessage(), e);
        }
    }

    private void salvarQuestionarios(Map<String, Questionario> qs) {
        try {
            FileOutputStream out = new FileOutputStream("questionarios.bin");
            ObjectOutputStream oo = new ObjectOutputStream(out);
            oo.writeObject(qs);
            oo.close(); out.close();
        } catch (IOException e) {
            throw new InfraException("Falha ao persistir questionários: " + e.getMessage(), e);
        }
    }

    public static void save(Map<String, Curso> cursos, Map<String, Questionario> questionarios) {
        try {
            FileOutputStream out = new FileOutputStream("config.bin");
            ObjectOutputStream oo = new ObjectOutputStream(out);
            oo.writeExternal(cursos);
            oo.writeInt(questionarios.size()); // placeholder — melhor serializar como POJO conjunto
            oo.writeObject(questionarios);
            oo.close(); out.close();
        } catch (IOException e) {
            throw new InfraException("Falha ao persistir configuração admin: " + e.getMessage(), e);
        }
    }
}
```

> ⚠️ **Nota importante:** Serializar múltiplos tipos no mesmo objeto exige cuidado. Recomendo usar uma classe wrapper simples abaixo para evitar problemas de polymorfismo. Vou simplificar usando duas chaves separadas no mesmo arquivo JSON-like... na verdade, o mais robusto seria manter dois arquivos separados (já feito). Vou ajustar o `AdminManager` para usar os dois arquivos diretamente — mais limpo.

**Corrigindo o `AdminManager` para usar arquivos separados:**

```java
// business/control/AdminManager (versão final recomendada)
package business.control;

import infra.InfraException;
import infra.ClassFileLoader;
import business.model.Curso;
import business.model.Questionario;
import util.AdminLoginValidator;
import java.util.Map;
import javax.swing.JOptionPane;

public class AdminManager {

    private Map<String, Curso> cursos;
    private Map<String, Questionario> questionarios;
    private String userEmail;
    private boolean authenticated = false;

    public AdminManager() throws InfraException {
        ClassFileLoader cl = new ClassFileLoader();
        this.cursos          = cl.getCursos();
        this.questionarios   = cl.getQuestionarios();
        this.userEmail       = null;
    }

    // ---------- Autenticação ----------
    public void authenticate(String email, String password) throws InfraException {
        if (!AdminLoginValidator.checkAdminLogin(email, password)) {
            throw new InfraException("❌ Credenciais administrativas inválidas!");
        }
        this.userEmail = email;
        this.authenticated = true;
        JOptionPane.showMessageDialog(null, "✅ Bem-vindo(a), Administrador(a)!");
    }

    public boolean isAuthenticated()   { return authenticated; }
    public String getEmail()           { return userEmail; }
    public void logout() {
        authenticated = false; userEmail = null;
    }

    // ---------- CURSOS ----------
    public void addCurso(String nome, String cidade, String centro) {
        if (nome == null || nome.trim().isEmpty()) {
            JOptionPane.showMessageDialog(null, "❌ Nome do curso não pode ser vazio.");
            return;
        }
        cursos.put(nome.trim(), new Curso(nome.trim(), cidade, centro));
        ClassFileLoader.persistCursos();
        JOptionPane.showMessageDialog(null, "✅ Curso adicionado: " + nome);
    }

    public void viewCursos() {
        if (!authenticated) { showMsg("❌ Não autenticado."); return; }
        StringBuilder sb = new StringBuilder("📋 CURSOS REGISTRADOS\n======================\n");
        if (cursos.isEmpty()) sb.append("(Nenhum curso cadastrado)\n");
        else {
            for (Map.Entry<String,Curso> e : cursos.entrySet()) {
                sb.append("• " + e.getKey() + " | " + e.getValue().getCidade() + "/" + e.getValue().getCentro() + "\n");
            }
        }
        sb.append("======================\n");
        JOptionPane.showMessageDialog(null, sb.toString());
    }

    public void removeCurso(String nome) {
        if (!authenticated) { showMsg("❌ Não autenticado."); return; }
        if (!cursos.containsKey(nome)) {
            JOptionPane.showMessageDialog(null, "❌ Curso não encontrado!");
            return;
        }
        cursos.remove(nome);
        ClassFileLoader.persistCursos();
        JOptionPane.showMessageDialog(null, "✅ Curso removido: " + nome);
    }

    // ---------- QUESTIONÁRIOS ----------
    public void addQuestionario(String pergunta, String area) {
        if (pergunta == null || pergunta.trim().isEmpty()) {
            JOptionPane.showMessageDialog(null, "❌ Pergunta não pode ser vazia.");
            return;
        }
        questionarios.put(pergunta.trim(), new Questionario(pergunta.trim(), area.trim()));
        ClassFileLoader.persistQuestionarios();
        JOptionPane.showMessageDialog(null, "✅ Questionário adicionado.");
    }

    public void viewQuestionarios() {
        if (!authenticated) { showMsg("❌ Não autenticado."); return; }
        StringBuilder sb = new StringBuilder("📝 QUESTIONÁRIOS REGISTRADOS\n============================\n");
        if (questionarios.isEmpty()) sb.append("(Nenhum questionário cadastrado)\n");
        else {
            int id = 1;
            for (Map.Entry<String,Questionario> e : questionarios.entrySet()) {
                sb.append("[ID-" + id + "] ").append(e.getValue().getPergunta())
                    .append("\n     Área: ").append(e.getValue().getArea()).append("\n\n");
                id++;
            }
        }
        sb.append("===========================\n");
        JOptionPane.showMessageDialog(null, sb.toString());
    }

    public void removeQuestionario(String pergunta) {
        if (!authenticated) { showMsg("❌ Não autenticado."); return; }
        if (!questionarios.containsKey(pergunta)) {
            JOptionPane.showMessageDialog(null, "❌ Questionário não encontrado!");
            return;
        }
        questionarios.remove(pergunta);
        ClassFileLoader.persistQuestionarios();
        JOptionPane.showMessageDialog(null, "✅ Questionário removido.");
    }

    // ---------- Utilitário ----------
    private void showMsg(String msg) {
        JOptionPane.showMessageDialog(null, msg);
    }
}
