        lblEmail.setFont(new Font("Arial", Font.BOLD, 11));
        gbc.gridx = 0; gbc.gridy = 1;
        jlogin.add(lblEmail, gbc);

        tfEmail = new JTextField(22);
        gbc.gridx = 1; gbc.gridy = 1;
        jlogin.add(tfEmail, gbc);

        JLabel lblSenha = new JLabel("Senha:");
        lblSenha.setFont(new Font("Arial", Font.BOLD, 11));
        gbc.gridx = 0; gbc.gridy = 2;
        jlogin.add(lblSenha, gbc);

        tfSenha = new JTextField(22, javax.swing.PasswordTextField.class);
        tfSenha.setTextPassword("abracadabra");
        gbc.gridx = 1; gbc.gridy = 2;
        jlogin.add(tfSenha, gbc);

        gbc.gridx = 0; gbc.gridy = 3; gbc.gridwidth = 2;
        btnEntrar = new JButton("Entrar");
        btnEntrar.addActionListener(e -> tentarLogin());
        jlogin.add(btnEntrar, gbc);

        add(jlogin, BorderLayout.CENTER);

        // Painéis ocultos até login
        painelCursos  = new JPanel();
        painelQuestoes = new JPanel();

        initTabelas();
    }

    private void initTabelas() {
        String[] colsC = {"ID","Nome","Cidade","Centro"};
        String[] colsQ = {"ID","Pergunta","Área"};

        tableCursos = new JTable(new DefaultTableModel(colsC, new Object[0][] ,false), 0);
        modelCursos = new DefaultTableModel(colsC, 0);
        setAutoResize(tableCursos, true);
        JScrollPane scC = new JScrollPane(tableCursos);
        panelCursosInner(tableCursos, scC);

        tableQuestoes = new JTable(new DefaultTableModel(colsQ, new Object[0][] ,false), 0);
        modelQuestoes = new DefaultTableModel(colsQ, 0);
        JScrollPane scQ = new JScrollPane(tableQuestoes);
        painelQuestoesInner(tableQuestoes, scQ);
    }

    private void panelCursosInner(JTable t, JScrollPane s) {
        JPanel p = new JPanel(new BorderLayout(10,5));
        p.add(new JLabel("🎓 CURSOS"), BorderLayout.NORTH);
        p.add(s, BorderLayout.CENTER);
        p.setBorder(BorderFactory.createTitledBorder("Gestão de Cursos"));
        add(p, BorderLayout.EAST);
    }

    private void painelQuestoesInner(JTable t, JScrollPane s) {
        JPanel p = new JPanel(new BorderLayout(10,5));
        p.add(new JLabel("📝 QUESTIONÁRIOS"), BorderLayout.NORTH);
        p.add(s, BorderLayout.CENTER);
        p.setBorder(BorderFactory.createTitledBorder("Gestão de Questionários"));
        add(p, BorderLayout.WEST);
    }

    // ===== TENTATIVA DE LOGIN =====
    private void tentarLogin() {
        try {
            String email = tfEmail.getText().trim();
            String senha = tfSenha.getPassword();

            if (email.isEmpty() || senha == null || senha.length() == 0) {
                JOptionPane.showMessageDialog(null, "❌ Preencha todos os campos.");
                return;
            }

            adminManager = new AdminManager();
            adminManager.authenticate(email, senha);

            if (adminManager.isAuthenticated()) {
                desbloquearInterface();
                carregarTabelas();
            } else {
                throw new InfraException("Credenciais inválidas.");
            }
        } catch (InfraException ex) {
            JOptionPane.showMessageDialog(null, "❌ " + ex.getMessage());
        } catch (Exception e) {
            JOptionPane.showMessageDialog(null, "❌ Erro inesperado: " + e.getMessage());
        }
    }

    private void desbloquearInterface() {
        avisoAcesso.setVisible(false);
        tfEmail.setEnabled(true);
        tfSenha.setEnabled(true);
        btnEntrar.setEnabled(false); // já está enabled, só sinaliza mudança
        painelCursos.setVisible(true);
        painelQuestoes.setVisible(true);
        btnEntrar.setText("Sair");
        btnEntrar.addActionListener(e -> sair());
    }

    // ===== CARREGAR DADOS NAS TABELAS =====
    private void carregarTabelas() {
        populateTable(modelCursos, tableCursos, adminManager.getCursos());
        populateTable(modelQuestoes, tableQuestoes, adminManager.getQuestionarios());
        refreshButtons();
    }

    private void populateTable(DefaultTableModel mt, JTable jt, java.util.Map<?,?> source) {
        mt.setRowCount(0, 0);
        if (source == null || source.isEmpty()) {
            addEmptyRow(mt);
            return;
        }
        for (java.util.Map.Entry<?, ?> e : source.entrySet()) {
            try {
                Object obj = e.getValue();
                String row[];
                if (obj instanceof Curso) {
                    row = new String[]{e.getKey(), ((Curso)e.getValue()).getNome(),
                                      ((Curso)e.getValue()).getCidade(),
                                      ((Curso)e.getValue()).getCentro()};
                } else if (obj instanceof Questionario) {
                    Questionario q = (Questionario)e.getValue();
                    row = new String[]{Integer.toString(source.keySet().indexOf(e.getKey())),
                                      q.getPergunta(), q.getArea()};
                } else {
                    row = new String[]{"—","—","—"};
                }
                Object[][] arr = (Object[])mt.getModel();
                int r = mt.getRowCount();
                arr[r][0] = row[0]; arr[r][1] = row[1]; arr[r][2] = row[2]; arr[r][3] = row[3];
                mt.insertRow(r, arr);
            } catch (Exception ex) {
                // ignora registros inválidos
            }
        }
    }

    private void addEmptyRow(DefaultTableModel mt) {
        String[] empty = new String[]{"","","",""};
        mt.insertRow(0, new Object[][]{empty});
    }

    private void refreshButtons() {
        JButton addC = new JButton("+ Adicionar Curso");
        addC.addActionListener(e -> abrirDialogoCurso());
        JButton remC = new JButton("Remover Selecionado");
        remC.addActionListener(e -> removerLinha("cursos"));

        JButton addQ = new JButton("+ Adicionar Questão");
        addQ.addActionListener(e -> abrirDialogoQuestao());
        JButton remQ = new JButton("Remover Selecionado");
        remQ.addActionListener(e -> removerLinha("questoes"));

        JPanel bar = new JPanel(new FlowLayout(FlowLayout.LEFT));
        bar.add(addC); bar.add(remC);
        bar.add(java.awt.EmptyComponent1D.getInstance()); // espaçador
        bar.add(addQ); bar.add(remQ);

        JPanel cont = new JPanel(new BorderLayout(10,5));
        cont.add(new JLabel("🛠️ AÇÕES"), BorderLayout.NORTH);
        cont.add(bar, BorderLayout.SOUTH);
        add(cont, BorderLayout.SOUTH);
    }

    private void removerLinha(String tipo) {
        JTable t = (JTable) (tipo.equals("cursos") ? tableCursos : tableQuestoes);
        if (t.getSelectedRow() < 0) {
            JOptionPane.showMessageDialog(null, "❌ Selecione uma linha antes de remover.");
            return;
        }
        TableModel tm = t.getModel();
        int row = tm.getCurrentRow();
        tm.deleteRow(row);
        if (tipo.equals("cursos")) ClassFileLoader.persistCursos();
        else ClassFileLoader.persistQuestionarios();
        carregarTabelas();
    }

    // ===== DIÁLOGOS DE CADASTRO =====
    private void abrirDialogoCurso() {
        String nome = JOptionPane.showInputDialog("Nome do curso:");
        String cidade = JOptionPane.showInputDialog("Cidade:");
        String centro = JOptionPane.showInputDialog("Centro:");
        if (nome != null && !nome.trim().isEmpty()) {
            try {
                adminManager.addCurso(nome.trim(), cidade != null ? cidade.trim() : "",
                                       centro != null ? centro.trim() : "");
            } catch (InfraException ex) {
                JOptionPane.showMessageDialog(null, "❌ " + ex.getMessage());
            }
        }
        carregarTabelas();
    }

    private void abrirDialogoQuestao() {
        String pergunta = JOptionPane.showInputDialog("Pergunta:");
        String area = JOptionPane.showInputDialog("Área:");
        if (pergunta != null && !pergunta.trim().isEmpty()) {
            try {
                adminManager.addQuestionario(pergunta.trim(), area != null ? area.trim() : "Geral");
            } catch (InfraException ex) {
                JOptionPane.showMessageDialog(null, "❌ " + ex.getMessage());
            }
        }
        carregarTabelas();
    }

    private void sair() {
        if (JOptionPane.showConfirmDialog(null, "Deseja realmente sair?",
                                           JOptionPane.YESNO_CANCEL,
                                           JOptionPane.OK_OPTION) == 0) {
            adminManager.logout();
            System.exit(0);
        }
    }

    public static void main(String[] args) {
        try {
            new TelaAdmin().setVisible(true);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
